/// The recorded `Date.parse` of a string; `NaN` when the string never reached `Date.parse`.
pub fn date_parse(s: &str) -> f64 {
    match DATE_PARSED.binary_search_by(|(k, _)| (*k).cmp(s)) {
        Ok(i) => DATE_PARSED[i].1,
        Err(_) => f64::NAN,
    }
}
